class Asset extends DataClass implements Insertable<Asset> {
  final String id;
  final String name;
  final String category;
  final String ownerMemberId;
  final String? businessId;
  final int purchaseDate;
  final int purchaseValueMinor;
  final int currentValueMinor;
  final String? notes;
  final String? photoPath;
  const Asset(
      {required this.id,
      required this.name,
      required this.category,
      required this.ownerMemberId,
      this.businessId,
      required this.purchaseDate,
      required this.purchaseValueMinor,
      required this.currentValueMinor,
      this.notes,
      this.photoPath});
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['name'] = Variable<String>(name);
    map['category'] = Variable<String>(category);
    map['owner_member_id'] = Variable<String>(ownerMemberId);
    if (!nullToAbsent || businessId != null) {
      map['business_id'] = Variable<String>(businessId);
    }
    map['purchase_date'] = Variable<int>(purchaseDate);
    map['purchase_value_minor'] = Variable<int>(purchaseValueMinor);
    map['current_value_minor'] = Variable<int>(currentValueMinor);
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    if (!nullToAbsent || photoPath != null) {
      map['photo_path'] = Variable<String>(photoPath);
    }
    return map;
  }

  AssetsCompanion toCompanion(bool nullToAbsent) {
    return AssetsCompanion(
      id: Value(id),
      name: Value(name),
      category: Value(category),
      ownerMemberId: Value(ownerMemberId),
      businessId: businessId == null && nullToAbsent
          ? const Value.absent()
          : Value(businessId),
      purchaseDate: Value(purchaseDate),
      purchaseValueMinor: Value(purchaseValueMinor),
      currentValueMinor: Value(currentValueMinor),
      notes:
          notes == null && nullToAbsent ? const Value.absent() : Value(notes),
      photoPath: photoPath == null && nullToAbsent
          ? const Value.absent()
          : Value(photoPath),
    );
  }

  factory Asset.fromJson(Map<String, dynamic> json,
      {ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Asset(
      id: serializer.fromJson<String>(json['id']),
      name: serializer.fromJson<String>(json['name']),
      category: serializer.fromJson<String>(json['category']),
      ownerMemberId: serializer.fromJson<String>(json['ownerMemberId']),
      businessId: serializer.fromJson<String?>(json['businessId']),
      purchaseDate: serializer.fromJson<int>(json['purchaseDate']),
      purchaseValueMinor: serializer.fromJson<int>(json['purchaseValueMinor']),
      currentValueMinor: serializer.fromJson<int>(json['currentValueMinor']),
      notes: serializer.fromJson<String?>(json['notes']),
      photoPath: serializer.fromJson<String?>(json['photoPath']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'name': serializer.toJson<String>(name),
      'category': serializer.toJson<String>(category),
      'ownerMemberId': serializer.toJson<String>(ownerMemberId),
      'businessId': serializer.toJson<String?>(businessId),
      'purchaseDate': serializer.toJson<int>(purchaseDate),
      'purchaseValueMinor': serializer.toJson<int>(purchaseValueMinor),
      'currentValueMinor': serializer.toJson<int>(currentValueMinor),
      'notes': serializer.toJson<String?>(notes),
      'photoPath': serializer.toJson<String?>(photoPath),
    };
  }

  Asset copyWith(
          {String? id,
          String? name,
          String? category,
          String? ownerMemberId,
          Value<String?> businessId = const Value.absent(),
          int? purchaseDate,
          int? purchaseValueMinor,
          int? currentValueMinor,
          Value<String?> notes = const Value.absent(),
          Value<String?> photoPath = const Value.absent()}) =>
      Asset(
        id: id ?? this.id,
        name: name ?? this.name,
        category: category ?? this.category,
        ownerMemberId: ownerMemberId ?? this.ownerMemberId,
        businessId: businessId.present ? businessId.value : this.businessId,
        purchaseDate: purchaseDate ?? this.purchaseDate,
        purchaseValueMinor: purchaseValueMinor ?? this.purchaseValueMinor,
        currentValueMinor: currentValueMinor ?? this.currentValueMinor,
        notes: notes.present ? notes.value : this.notes,
        photoPath: photoPath.present ? photoPath.value : this.photoPath,
      );
  Asset copyWithCompanion(AssetsCompanion data) {
    return Asset(
      id: data.id.present ? data.id.value : this.id,
      name: data.name.present ? data.name.value : this.name,
      category: data.category.present ? data.category.value : this.category,
      ownerMemberId: data.ownerMemberId.present
          ? data.ownerMemberId.value
          : this.ownerMemberId,
      businessId:
          data.businessId.present ? data.businessId.value : this.businessId,
      purchaseDate: data.purchaseDate.present
          ? data.purchaseDate.value
          : this.purchaseDate,
      purchaseValueMinor: data.purchaseValueMinor.present
          ? data.purchaseValueMinor.value
          : this.purchaseValueMinor,
      currentValueMinor: data.currentValueMinor.present
          ? data.currentValueMinor.value
          : this.currentValueMinor,
      notes: data.notes.present ? data.notes.value : this.notes,
      photoPath: data.photoPath.present ? data.photoPath.value : this.photoPath,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Asset(')
          ..write('id: $id, ')
          ..write('name: $name, ')
          ..write('category: $category, ')
          ..write('ownerMemberId: $ownerMemberId, ')
          ..write('businessId: $businessId, ')
          ..write('purchaseDate: $purchaseDate, ')
          ..write('purchaseValueMinor: $purchaseValueMinor, ')
          ..write('currentValueMinor: $currentValueMinor, ')
          ..write('notes: $notes, ')
          ..write('photoPath: $photoPath')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(id, name, category, ownerMemberId, businessId,
      purchaseDate, purchaseValueMinor, currentValueMinor, notes, photoPath);
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is Asset &&
          other.id == this.id &&
          other.name == this.name &&
          other.category == this.category &&
          other.ownerMemberId == this.ownerMemberId &&
          other.businessId == this.businessId &&
          other.purchaseDate == this.purchaseDate &&
          other.purchaseValueMinor == this.purchaseValueMinor &&
          other.currentValueMinor == this.currentValueMinor &&
          other.notes == this.notes &&
          other.photoPath == this.photoPath);
}

