              {familyMemberId = false,
              businessId = false,
              categoryId = false,
              accountId = false,
              createdByMemberId = false,
              transactionEntriesRefs = false,
              transactionAttachmentsRefs = false,
              partyPaymentsRefs = false,
              cattleExpensesRefs = false,
              loanPaymentsRefs = false}) {
            return PrefetchHooks(
              db: db,
              explicitlyWatchedTables: [
                if (transactionEntriesRefs) db.transactionEntries,
                if (transactionAttachmentsRefs) db.transactionAttachments,
                if (partyPaymentsRefs) db.partyPayments,
                if (cattleExpensesRefs) db.cattleExpenses,
                if (loanPaymentsRefs) db.loanPayments
