                    currentTable: table,
                    currentColumn: table.familyMemberId,
                    referencedTable:
                        $$TransactionsTableReferences._familyMemberIdTable(db),
                    referencedColumn: $$TransactionsTableReferences
                        ._familyMemberIdTable(db)
                        .id,
