                        $$TransactionsTableReferences._categoryIdTable(db),
                    referencedColumn:
                        $$TransactionsTableReferences._categoryIdTable(db).id,
                  ) as T;
                }
                if (accountId) {
                  state = state.withJoin(
                    currentTable: table,
                    currentColumn: table.accountId,
                    referencedTable:
                        $$TransactionsTableReferences._accountIdTable(db),
                    referencedColumn:
                        $$TransactionsTableReferences._accountIdTable(db).id,
                  ) as T;
                }
                if (createdByMemberId) {
                  state = state.withJoin(
                    currentTable: table,
                    currentColumn: table.createdByMemberId,
                    referencedTable: $$TransactionsTableReferences
                        ._createdByMemberIdTable(db),
                    referencedColumn: $$TransactionsTableReferences
                        ._createdByMemberIdTable(db)
                        .id,
                  ) as T;
                }

                return state;
              },
              getPrefetchedDataCallback: (items) async {
                return [
                  if (transactionEntriesRefs)
                    await $_getPrefetchedData<Transaction, $TransactionsTable, TransactionEntry>(
                        currentTable: table,
                        referencedTable: $$TransactionsTableReferences
                            ._transactionEntriesRefsTable(db),
                        managerFromTypedResult: (p0) =>
                            $$TransactionsTableReferences(db, table, p0)
                                .transactionEntriesRefs,
                        referencedItemsForCurrentItem:
