              $$ProductsTableFilterComposer($db: db, $table: table),
          createOrderingComposer: () =>
              $$ProductsTableOrderingComposer($db: db, $table: table),
          createComputedFieldComposer: () =>
              $$ProductsTableAnnotationComposer($db: db, $table: table),
          updateCompanionCallback: ({
            Value<String> id = const Value.absent(),
            Value<String> businessId = const Value.absent(),
            Value<String?> sku = const Value.absent(),
            Value<String?> barcode = const Value.absent(),
            Value<String> name = const Value.absent(),
            Value<String?> nameBn = const Value.absent(),
            Value<String?> nameEn = const Value.absent(),
            Value<String?> categoryId = const Value.absent(),
            Value<String?> subcategoryId = const Value.absent(),
            Value<String> unit = const Value.absent(),
            Value<String?> packageUnit = const Value.absent(),
            Value<double> packageQuantity = const Value.absent(),
            Value<int> purchasePriceMinor = const Value.absent(),
            Value<int> sellingPriceMinor = const Value.absent(),
            Value<int> wholesalePriceMinor = const Value.absent(),
            Value<String?> brand = const Value.absent(),
            Value<String?> imagePath = const Value.absent(),
            Value<String?> description = const Value.absent(),
            Value<int?> expiryDate = const Value.absent(),
            Value<String?> batchNumber = const Value.absent(),
            Value<String?> defaultSupplierId = const Value.absent(),
            Value<double> openingQuantity = const Value.absent(),
            Value<double> minimumStock = const Value.absent(),
            Value<int> isActive = const Value.absent(),
            Value<int> createdAt = const Value.absent(),
            Value<int> rowid = const Value.absent(),
          }) =>
              ProductsCompanion(
            id: id,
            businessId: businessId,
            sku: sku,
            barcode: barcode,
            name: name,
            nameBn: nameBn,
            nameEn: nameEn,
            categoryId: categoryId,
            subcategoryId: subcategoryId,
            unit: unit,
            packageUnit: packageUnit,
            packageQuantity: packageQuantity,
            purchasePriceMinor: purchasePriceMinor,
            sellingPriceMinor: sellingPriceMinor,
            wholesalePriceMinor: wholesalePriceMinor,
            brand: brand,
            imagePath: imagePath,
            description: description,
            expiryDate: expiryDate,
            batchNumber: batchNumber,
            defaultSupplierId: defaultSupplierId,
            openingQuantity: openingQuantity,
            minimumStock: minimumStock,
            isActive: isActive,
            createdAt: createdAt,
            rowid: rowid,
          ),
          createCompanionCallback: ({
            required String id,
            required String businessId,
            Value<String?> sku = const Value.absent(),
            Value<String?> barcode = const Value.absent(),
            required String name,
            Value<String?> nameBn = const Value.absent(),
            Value<String?> nameEn = const Value.absent(),
            Value<String?> categoryId = const Value.absent(),
            Value<String?> subcategoryId = const Value.absent(),
            required String unit,
            Value<String?> packageUnit = const Value.absent(),
            Value<double> packageQuantity = const Value.absent(),
            Value<int> purchasePriceMinor = const Value.absent(),
            Value<int> sellingPriceMinor = const Value.absent(),
            Value<int> wholesalePriceMinor = const Value.absent(),
            Value<String?> brand = const Value.absent(),
            Value<String?> imagePath = const Value.absent(),
            Value<String?> description = const Value.absent(),
            Value<int?> expiryDate = const Value.absent(),
            Value<String?> batchNumber = const Value.absent(),
            Value<String?> defaultSupplierId = const Value.absent(),
            Value<double> openingQuantity = const Value.absent(),
            Value<double> minimumStock = const Value.absent(),
            Value<int> isActive = const Value.absent(),
            required int createdAt,
            Value<int> rowid = const Value.absent(),
          }) =>
              ProductsCompanion.insert(
            id: id,
            businessId: businessId,
            sku: sku,
            barcode: barcode,
            name: name,
            nameBn: nameBn,
            nameEn: nameEn,
            categoryId: categoryId,
            subcategoryId: subcategoryId,
            unit: unit,
            packageUnit: packageUnit,
            packageQuantity: packageQuantity,
            purchasePriceMinor: purchasePriceMinor,
            sellingPriceMinor: sellingPriceMinor,
            wholesalePriceMinor: wholesalePriceMinor,
            brand: brand,
            imagePath: imagePath,
            description: description,
            expiryDate: expiryDate,
            batchNumber: batchNumber,
            defaultSupplierId: defaultSupplierId,
            openingQuantity: openingQuantity,
            minimumStock: minimumStock,
            isActive: isActive,
            createdAt: createdAt,
            rowid: rowid,
          ),
          withReferenceMapper: (p0) => p0
              .map((e) =>
                  (e.readTable(table), $$ProductsTableReferences(db, table, e)))
              .toList(),
          prefetchHooksCallback: (
              {businessId = false,
              categoryId = false,
              subcategoryId = false,
              defaultSupplierId = false,
              productUnitConversionsRefs = false,
              productPriceTiersRefs = false,
              inventoryMovementsRefs = false,
              purchaseItemsRefs = false,
              salesItemsRefs = false}) {
            return PrefetchHooks(
              db: db,
              explicitlyWatchedTables: [
                if (productUnitConversionsRefs) db.productUnitConversions,
                if (productPriceTiersRefs) db.productPriceTiers,
                if (inventoryMovementsRefs) db.inventoryMovements,
                if (purchaseItemsRefs) db.purchaseItems,
                if (salesItemsRefs) db.salesItems
              ],
              addJoins: <
                  T extends TableManagerState<
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic>>(state) {
                if (businessId) {
                  state = state.withJoin(
